import {uid,dateKey,addDays,effectiveDate,timePosition,clockNow,eventStamp,freshData,dayOf,ensureDay,habitDue,habitCount,aggregate,average,validateBackup,validDate} from './core.js';
import {openDB,writeDB} from './db.js';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],app=$('#app'),modal=$('#modal');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6 7 7m10 10 1.4 1.4M5.6 18.4 7 17M17 7l1.4-1.4M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',book:'M3 4h6c2 0 3 1 3 2v15c0-2-1-3-3-3H3V4m18 0h-6c-2 0-3 1-3 2m0 15c0-2 1-3 3-3h6V4',check:'m5 12 4 4L19 6',history:'M3 11a9 9 0 1 1 2 7M3 5v6h6m3-4v6l4 2',settings:'M4 6h16M4 12h16M4 18h16M8 3v6m8 0v6m-6 0v6',plus:'M12 5v14M5 12h14',drop:'M12 3C10 7 5 11 5 15a7 7 0 0 0 14 0c0-4-5-8-7-12Z',heart:'M20 5a5 5 0 0 0-8 1 5 5 0 0 0-8-1c-4 4 1 9 8 15 7-6 12-11 8-15Z',pill:'m8 16 8-8m-11 3 6-6a5.7 5.7 0 0 1 8 8l-6 6a5.7 5.7 0 0 1-8-8Z',moon:'M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11Z',activity:'M3 12h4l3-8 4 16 3-8h4',note:'M5 3h14v18H5V3m4 5h6m-6 4h6m-6 4h4',body:'M12 3v3m-5 2h10m-5-2v9m0 0-5 6m5-6 5 6',left:'m15 5-7 7 7 7',right:'m9 5 7 7-7 7',close:'m6 6 12 12M6 18 18 6',edit:'m4 16 12-12 4 4L8 20H4v-4m9-9 4 4',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',camera:'M3 7h4l2-3h6l2 3h4v14H3V7m13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0',leaf:'M5 20 19 6M4 16C1 6 10 3 21 3c0 11-3 20-13 17',calendar:'M4 5h16v16H4V5m0 5h16M8 3v4m8-4v4'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.note}"/></svg>`;
const btn=(action,label,cls='',attrs='')=>`<button type="button" data-action="${action}" class="${cls}" ${attrs}>${label}</button>`;
const prettyDate=key=>new Intl.DateTimeFormat('pl',{day:'numeric',month:'long'}).format(new Date(key+'T12:00:00'));
const weekday=key=>new Intl.DateTimeFormat('pl',{weekday:'long'}).format(new Date(key+'T12:00:00'));
const names={mood:'Samopoczucie',drink:'Napój',symptom:'Objaw',med:'Lek / suplement',activity:'Zdarzenie',sleep:'Sen',bowel:'Wypróżnienie',note:'Notatka'};
const eventIcons={mood:'sun',drink:'drop',symptom:'heart',med:'pill',activity:'activity',sleep:'moon',bowel:'body',note:'note'};
let data,selected=effectiveDate(),view='today',range=7,calendarMonth=selected.slice(0,7),saveQueue=Promise.resolve(),saveError='',savePending=0,installPrompt=null;
const collapsed=new Set();
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4200)}
function applyTheme(){const theme=data.settings.theme;document.documentElement.dataset.theme=theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):theme;document.querySelector('meta[name=theme-color]').content=getComputedStyle(document.documentElement).getPropertyValue('--bg').trim()}
function status(){const msg=saveError?'Błąd zapisu':savePending?'Zapisuję…':'Zapisano na tym urządzeniu';$$('.save-status').forEach(n=>n.textContent=msg)}
function persist({all=false,date=selected}={}){
 const {days,...meta}=data;const snapshot={...structuredClone(meta),days:structuredClone(all?days:(days[date]?{[date]:days[date]}:{}))};savePending++;status();
 const operation=saveQueue.then(async()=>{if(saveError)throw Error(saveError);const expected=data.rev;snapshot.rev=expected+1;try{await writeDB(snapshot,expected,all);data.rev=snapshot.rev;}catch(e){saveError=e.message;renderSaveError();throw e}});
 saveQueue=operation.catch(()=>{});operation.finally(()=>{savePending--;status()}).catch(()=>{});return operation;
}
function renderSaveError(){if(!$('#save-error')){const n=document.createElement('div');n.id='save-error';n.className='banner';n.innerHTML=`<strong>Zmiany nie są zapisane.</strong> ${esc(saveError)} ${btn('backup','Pobierz kopię bieżących danych','text-btn')}`;$('.page')?.prepend(n)}toast('Nie udało się zapisać. Zrób kopię bieżących danych.')}
function navigate(next){view=next;if(next==='journal')collapsed.clear();render();window.scrollTo(0,0)}
function dateControls(){return `<div class="date-nav">${btn('prev',icon('left'),'icon-btn','aria-label="Poprzedni dzień"')}<label><span class="visually-hidden">Dzień dziennika</span><input type="date" id="selected-date" value="${selected}" max="${effectiveDate()}"></label>${btn('next',icon('right'),'icon-btn',`aria-label="Następny dzień" ${selected>=effectiveDate()?'disabled':''}`)}</div>`}
function header(title,subtitle=''){return `<div class="page-head"><div class="row between wrap"><p class="eyebrow">${weekday(selected)} · ${prettyDate(selected)}</p><span class="save-status"></span></div><h1>${title}</h1>${subtitle?`<p class="muted">${subtitle}</p>`:''}<div class="row between date-line">${dateControls()}${selected!==effectiveDate()?btn('today','Wróć do dziś','text-btn'):''}</div></div>`}
function render(){
 applyTheme();app.innerHTML=`<div class="shell"><header class="topbar"><div class="brand">Blisko<span>✳</span></div><div class="top-actions"><span class="save-status"></span>${btn('install',icon('download'),'icon-btn',`aria-label="Zainstaluj aplikację" title="Zainstaluj aplikację"`)}${btn('settings',icon('settings'),`icon-btn ${view==='settings'?'secondary':''}`,'aria-label="Ustawienia"')}</div></header><div class="layout"><nav aria-label="Główna nawigacja">${[['today','sun','Dziś'],['journal','book','Dziennik'],['habits','check','Nawyki'],['history','history','Historia']].map(([id,ic,name])=>btn('nav',icon(ic)+name,view===id?'active':'',`data-view="${id}" ${view===id?'aria-current="page"':''}`)).join('')}<div class="nav-foot">Trochę bliżej siebie.<br>We własnym tempie.<br><br><span class="small">${icon('leaf')} Twój prywatny notes</span></div></nav><main class="page" id="main">${view==='today'?todayView():view==='journal'?journalView():view==='habits'?habitsView():view==='history'?historyView():settingsView()}</main></div></div>`;
 status();if(saveError)renderSaveError();if(view==='journal')$$('details').forEach(el=>el.addEventListener('toggle',()=>{if(el.open)collapsed.delete(el.id);else collapsed.add(el.id)}));
}
function eventLabel(e){if(e.type==='mood')return ['mood','energy','productivity'].filter(k=>e[k]!=null).map(k=>`${{mood:'Nastrój',energy:'Energia',productivity:'Produktywność'}[k]} ${e[k]}/10`).join(' · ');if(e.type==='drink')return `${e.name} · ${e.ml} ml`;if(e.type==='symptom')return `${e.name} · ${['','łagodny','umiarkowany','silny'][e.severity]}`;if(e.type==='med')return `${e.name}${e.dose?' · '+e.dose:''}`;if(e.type==='sleep')return `Sen · ${e.quality}${e.hours?' · '+e.hours+' h':''}`;if(e.type==='bowel')return `Wypróżnienie · ${e.stool||'zapisane'}`;return e.name||names[e.type]}
function timeline(events){if(!events.length)return `<div class="empty">${icon('note')}<p>Jeszcze czysta kartka.</p><p>Dodaj pierwszy wpis, kiedy zechcesz.</p></div>`;return `<ol class="timeline">${[...events].sort((a,b)=>timePosition(b.time)-timePosition(a.time)).map(e=>`<li><time>${esc(e.time)}</time><span class="event-icon">${icon(eventIcons[e.type])}</span><button class="event-edit" data-action="edit-event" data-id="${e.id}" aria-label="Edytuj: ${esc(eventLabel(e))}"><strong>${esc(eventLabel(e))}</strong>${e.note?`<span>${esc(e.note)}</span>`:''}</button>${btn('delete-event',icon('close'),'delete',`data-id="${e.id}" aria-label="Usuń wpis: ${esc(eventLabel(e))}"`)}</li>`).join('')}</ol>`}
function todayView(){const day=dayOf(data,selected),m=day.events.filter(e=>e.type==='mood'),last=[...m].sort((a,b)=>timePosition(b.time)-timePosition(a.time))[0];const water=day.events.filter(e=>e.type==='drink'&&e.ref==='water').reduce((n,e)=>n+e.ml,0);return `${header('Jak Ci dzisiaj?','Jest miejsce na wszystko, co przynosi dzień.')}<div class="grid"><div class="stack"><section class="card feature"><span class="motif" aria-hidden="true">✳</span><p class="eyebrow">Chwila dla siebie</p><h2>Zatrzymaj się.<br>Co czujesz teraz?</h2><p class="small">Nastrój, energia i produktywność.</p>${btn('add-event','Zapisz samopoczucie '+icon('plus'),'','data-type="mood"')}${last?`<p class="small" style="margin-top:16px;margin-bottom:0">Ostatnio, ${last.time}: ${esc(eventLabel(last))}</p>`:''}</section><section class="card"><h2>Zapisz na bieżąco</h2><div class="quick-grid">${Object.entries(names).filter(([k])=>k!=='mood').map(([k,name])=>btn('add-event',icon(eventIcons[k])+`<span>${name}</span>`,'quick',`data-type="${k}"`)).join('')}</div><div class="metric-row"><div class="metric"><strong>${water}<small> ml</small></strong><span>Wypita woda</span></div><div class="metric"><strong>${m.length}</strong><span>Chwile zatrzymania</span></div><div class="metric"><strong>${day.events.filter(e=>e.type==='symptom').length}</strong><span>Zapisane objawy</span></div></div></section><section class="card"><p class="eyebrow">Na koniec dnia</p><h2>Umysł. Ciało. Serce.</h2><p class="muted small">${Object.keys(day.journal).length?'Twoja refleksja już tutaj czeka. Możesz do niej wrócić.':'Kilka chwil, żeby usłyszeć siebie.'}</p>${btn('journal','Otwórz dziennik '+icon('right'),'text-btn')}</section></div><div class="stack"><section class="card"><div class="row between"><h2>Małe kroki</h2>${btn('habits','Wszystkie','text-btn')}</div>${habitRows(true)}</section><section class="card"><div class="row between"><h2>Ślady dnia</h2><span class="eyebrow">${day.events.length} wpisów</span></div>${timeline(day.events)}</section></div></div>`}
const textField=(label,name,value='',placeholder='',type='text',attrs='')=>`<label class="field"><span>${label}</span>${type==='textarea'?`<textarea name="${name}" placeholder="${placeholder}" ${attrs}>${esc(value)}</textarea>`:`<input type="${type}" name="${name}" value="${esc(value)}" placeholder="${placeholder}" ${attrs}>`}</label>`;
function options(label,name,values,current,{scale=false,journal=false}={}){return `<fieldset><legend>${label}</legend><div class="${scale?'scale':'choices'}">${values.map(v=>{const [value,text]=Array.isArray(v)?v:[v,v];return `<label class="choice"><input type="radio" name="${name}" value="${esc(value)}" ${String(current)===String(value)?'checked':''} ${journal?'data-journal':''}><span>${esc(text)}</span></label>`}).join('')}</div>${scale?'<div class="scale-caption"><span>Nisko</span><span>Wysoko</span></div>':''}</fieldset>`}
const scale=(label,name,value,journal=false)=>options(label,name,Array.from({length:10},(_,i)=>i+1),value,{scale:true,journal});
function journalView(){const j=dayOf(data,selected).journal;const tf=(label,key,placeholder='Możesz też zostawić to pole puste.')=>textField(label,key,j[key]||'',placeholder,'textarea','data-journal maxlength="20000"');const op=(label,key,values)=>options(label,key,values,j[key],{journal:true});const section=(id,n,title,content,wide=false)=>`<details id="${id}" class="card section ${wide?'wide':''}" ${collapsed.has(id)?'':'open'}><summary><span><span class="section-number">${n}</span>${title}</span></summary><div class="section-body">${content}</div></details>`;const sleep=dayOf(data,selected).events.find(e=>e.type==='sleep');const needs=(title,key,items)=>`<div class="field"><span>${title}</span><div class="chips">${items.map(t=>btn('need-chip',esc(t),`chip ${(j[key+'Tags']||[]).includes(t)?'selected':''}`,`data-key="${key}Tags" data-value="${esc(t)}" aria-pressed="${(j[key+'Tags']||[]).includes(t)}"`)).join('')}</div></div>${tf('Coś jeszcze?',key,'Twoimi słowami…')}`;return `${header('Moja wieczorna kartka','Nie musisz wypełniać wszystkiego. Wystarczy tyle, ile dziś chcesz.')}<div class="journal">${section('rating','01','Jaki to był dzień?',scale('Moja ocena całego dnia','rating',j.rating,true),true)}${section('mind','02','Umysł',op('Mój umysł był dzisiaj w…','mind',['przeszłości','teraźniejszości','przyszłości'])+tf('Jedna rzecz, która była dla mnie ciężarem / wsparciem','mindNote'))}${section('body','03','Ciało',op('Stres','stress',['niski','średni','wysoki'])+op('Energia w całym dniu','dayEnergy',['niska','średnia','wysoka'])+`<div class="field"><span>Sen z ostatniej nocy</span><p class="small muted">${sleep?esc(eventLabel(sleep)):'Jeszcze bez wpisu'}</p>${btn('add-event',sleep?'Zmień zapis snu':'Zapisz sen','secondary','data-type="sleep"')}</div>`+op('Ruch','movement',['lekki','wystarczający','duży'])+tf('Jedno odczucie z ciała, które zauważyłeś','bodyNote'))}${section('heart','04','Serce',op('Jakie masz dzisiaj serce?','heart',['lekkie','normalne','ciężkie'])+tf('Czuję się tak, ponieważ…','heartNote'))}${section('needs','05','Czego dziś potrzebuję?',needs('Dzisiaj mój umysł potrzebuje','mindNeeds',['ciszy','skupienia','odpoczynku','jasności','mniej bodźców'])+needs('Dzisiaj moje serce potrzebuje','heartNeeds',['bliskości','rozmowy','przestrzeni','wsparcia','zabawy'])+needs('Dzisiaj moje ciało potrzebuje','bodyNeeds',['snu','ruchu','rozciągania','jedzenia','odpoczynku']))}${section('pleasant','06','Trzy przyjemne chwile',[1,2,3].map(n=>textField(`${n}. Nawet coś niewielkiego`,`pleasant${n}`,j['pleasant'+n]||'','Co było przyjemne?','text','data-journal maxlength="1000"')).join(''))}${section('photo','07','Zdjęcie dnia',j.photo?`<img class="photo" src="${j.photo}" alt="Zdjęcie dnia ${prettyDate(selected)}">${btn('remove-photo','Usuń zdjęcie','text-btn danger')}`:`<label class="photo-pick">${icon('camera')}<p style="margin-top:10px">Zachowaj jedną chwilę</p><span class="small muted">Wybierz zdjęcie z galerii</span><input type="file" id="day-photo" accept="image/*"></label>`)}${section('notes','08','Miejsce na Twoje słowa',tf('Notatki','notes','Co chcesz zapamiętać?'),true)}</div>`}
function habitSchedule(h){if(h.mode==='weekly')return `${h.target} razy w tygodniu · dowolne dni`;const days=['nd.','pon.','wt.','śr.','czw.','pt.','sob.'];return (h.mode==='days'?h.weekdays.map(d=>days[d]).join(', '):'codziennie')+(h.time?' · '+h.time:'')}
function habitRows(compact=false){const habits=data.habits.filter(h=>habitDue(h,selected));if(!habits.length)return `<div class="empty">${icon('leaf')}<p>${data.habits.length?'Dzisiaj bez zaplanowanych nawyków.':'Małe rzeczy tworzą codzienność.'}</p>${btn('new-habit','Dodaj nawyk','text-btn')}</div>`;return habits.map(h=>{const checks=dayOf(data,selected).checks[h.id]||[],count=habitCount(data,h,selected);return `<div class="habit"><div class="habit-title"><div><h3>${esc(h.name)}</h3><span class="small muted">${esc(habitSchedule(h))}</span></div>${!compact?btn('edit-habit',icon('edit'),'icon-btn',`data-id="${h.id}" aria-label="Edytuj nawyk ${esc(h.name)}"`):''}</div><div class="habit-slots">${h.mode==='weekly'?`${btn('habit-increment',icon('plus')+' Wykonane','habit-check',`data-id="${h.id}" ${count>=h.target?'disabled':''}`)}<span class="small muted" style="align-self:center">${count}/${h.target} w tym tygodniu</span>${checks.some(Boolean)?btn('habit-undo','Cofnij dzisiejsze','text-btn',`data-id="${h.id}"`):''}`:Array.from({length:h.target},(_,i)=>btn('habit-check',`<span class="box">${checks[i]?'✓':''}</span>${esc(h.slots[i]|| (h.target===1?'Zrobione':`${i+1}. raz`))}`,`habit-check ${checks[i]?'done':''}`,`data-id="${h.id}" data-slot="${i}" aria-pressed="${!!checks[i]}"`)).join('')}</div></div>`}).join('')}
function habitsView(){const notToday=data.habits.filter(h=>!h.endDate&&!habitDue(h,selected));const archived=data.habits.filter(h=>h.endDate);return `${header('Moje małe kroki','Regularność we własnym rytmie.')}<div class="grid"><section class="card"><div class="row between"><h2>Na ten dzień</h2>${btn('new-habit',icon('plus'),'icon-btn','aria-label="Dodaj nawyk"')}</div>${habitRows()}</section><div class="stack"><section class="card"><h2>Twój rytm</h2><p class="muted small">Codziennie, w wybrane dni albo kilka razy w tygodniu. Możesz rozdzielić poranek i wieczór.</p>${btn('new-habit','Utwórz nawyk','primary full')}<p class="small muted" style="margin-top:16px">Godziny są wskazówką w planie dnia. Powiadomienia dodamy w kolejnej wersji.</p></section>${notToday.length?`<section class="card"><h2>W pozostałe dni</h2>${notToday.map(h=>`<div class="list-row"><div><strong>${esc(h.name)}</strong><small>${esc(habitSchedule(h))}</small></div>${btn('edit-habit',icon('edit'),'icon-btn',`data-id="${h.id}" aria-label="Edytuj ${esc(h.name)}"`)}</div>`).join('')}</section>`:''}${archived.length?`<details class="card"><summary>Archiwum (${archived.length})</summary>${archived.map(h=>`<div class="list-row"><span>${esc(h.name)}</span>${btn('restore-habit','Przywróć','text-btn',`data-id="${h.id}"`)}</div>`).join('')}</details>`:''}</div></div>`}
function chartView(){const points=range===1?dayOf(data,selected).events.filter(e=>e.type==='mood').sort((a,b)=>timePosition(a.time)-timePosition(b.time)):aggregate(data,selected,range);const series=[['mood','Nastrój','var(--accent)'],['energy','Energia','var(--gold)'],['productivity','Produktywność','var(--rose)']];const width=600,height=240,pad=30,x=(p,i)=>range===1?pad+timePosition(p.time)/24*(width-2*pad):pad+(range===1?0.5:i/Math.max(1,range-1))*(width-2*pad),y=v=>height-30-(v-1)/9*(height-55);const has=points.some(p=>series.some(([k])=>p[k]!=null));return `<div class="legend">${series.map(([,n,c])=>`<span style="--c:${c}">${n}</span>`).join('')}</div>${has?`<svg class="chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Wykres nastroju, energii i produktywności w skali od 1 do 10">${[1,4,7,10].map(v=>`<line class="chart-grid" x1="${pad}" y1="${y(v)}" x2="${width-pad}" y2="${y(v)}"/><text x="8" y="${y(v)+4}">${v}</text>`).join('')}${series.map(([k,n,c])=>{let d='',active=false;points.forEach((p,i)=>{if(p[k]==null){active=false;return}d+=`${active?'L':'M'}${x(p,i)},${y(p[k])} `;active=true});return `<path d="${d}" fill="none" stroke="${c}" stroke-width="2.3"/>${points.map((p,i)=>p[k]==null?'':`<circle cx="${x(p,i)}" cy="${y(p[k])}" r="3.5" fill="${c}"><title>${range===1?p.time:p.date} · ${n}: ${p[k].toFixed(1)}</title></circle>`).join('')}`}).join('')}${range===1?[['04:00',30],['12:00',210],['20:00',390],['04:00',570]].map(([t,x])=>`<text x="${x}" y="235" text-anchor="middle">${t}</text>`).join(''):points.filter((p,i)=>i===0||i===Math.floor((range-1)/2)||i===range-1).map(p=>`<text x="${x(p,points.indexOf(p))}" y="235" text-anchor="middle">${p.date.slice(8)}.${p.date.slice(5,7)}</text>`).join('')}</svg><details style="margin-top:15px"><summary class="small">Pokaż wartości</summary><div style="overflow:auto"><table class="data-table"><thead><tr><th>${range===1?'Godzina':'Dzień'}</th><th>Nastrój</th><th>Energia</th><th>Produktywność</th></tr></thead><tbody>${points.map(p=>`<tr><td>${range===1?p.time:p.date}</td>${series.map(([k])=>`<td>${p[k]==null?'—':p[k].toFixed(1)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details>`:`<div class="empty">${icon('activity')}<p>Wykres zaczyna się od pierwszego wpisu.</p><p>Zapisuj samopoczucie w zakładce Dziś.</p></div>`}<p class="stat-note">${range===1?'Każdy punkt to osobny pomiar. Dzień trwa od 4:00 do 4:00.':'Punkty pokazują średnie dzienne z pomiarów chwilowych. Przerwy oznaczają brak danych.'} Wieczorna ocena dnia i energii pozostaje osobno.</p>`}
function calendarView(){const start=calendarMonth+'-01',offset=(new Date(start+'T12:00:00').getDay()+6)%7,count=new Date(Number(calendarMonth.slice(0,4)),Number(calendarMonth.slice(5)),0).getDate();return `<div class="row between" style="margin-bottom:16px">${btn('month-prev',icon('left'),'icon-btn','aria-label="Poprzedni miesiąc"')}<strong>${new Intl.DateTimeFormat('pl',{month:'long',year:'numeric'}).format(new Date(start+'T12:00:00'))}</strong>${btn('month-next',icon('right'),'icon-btn',`aria-label="Następny miesiąc" ${calendarMonth>=effectiveDate().slice(0,7)?'disabled':''}`)}</div><div class="calendar">${['P','W','Ś','C','P','S','N'].map(s=>`<span class="day-name">${s}</span>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:count},(_,i)=>{const key=calendarMonth+'-'+String(i+1).padStart(2,'0'),day=dayOf(data,key),has=day.events.length||Object.keys(day.journal).length||Object.keys(day.checks).length;return btn('calendar-day',`${i+1}${has?'<span class="dot"></span>':''}`,`${key===selected?'active':''} ${day.journal.photo?'has-photo':''}`,`data-date="${key}" aria-label="${prettyDate(key)}${has?', są wpisy':''}" ${key>effectiveDate()?'disabled':''} ${day.journal.photo?`style="background-image:linear-gradient(#0003,#0003),url('${day.journal.photo}')"`:''}`)}).join('')}</div>`}
function historyView(){const d=dayOf(data,selected),j=d.journal;const fields=[['rating','Ocena dnia'],['dayEnergy','Energia całego dnia'],['mind','Umysł'],['stress','Stres'],['heart','Serce']];return `${header('Z perspektywy czasu','Twoje chwile układają się w historię.')}<section class="card" style="margin-bottom:20px"><div class="row between wrap"><h2>Nastrój i rytm dnia</h2><div class="segment">${[1,7,30,90].map(n=>btn('range',n===1?'1 dzień':`${n} dni`,range===n?'active':'',`data-range="${n}" aria-pressed="${range===n}"`)).join('')}</div></div>${chartView()}</section><div class="grid"><section class="card"><h2>Kartki kalendarza</h2>${calendarView()}</section><div class="stack"><section class="card"><div class="row between"><h2>${prettyDate(selected)}</h2>${btn('journal','Otwórz kartkę','text-btn')}</div>${j.photo?`<img class="photo" src="${j.photo}" alt="Zdjęcie dnia">`:''}${Object.keys(j).length?`<div class="chips">${fields.filter(([k])=>j[k]!=null).map(([k,n])=>`<span class="chip secondary">${n}: ${esc(j[k])}${k==='rating'?'/10':''}</span>`).join('')}</div>${[1,2,3].filter(n=>j['pleasant'+n]).map(n=>`<p class="history-summary small" style="margin-top:12px">${n}. ${esc(j['pleasant'+n])}</p>`).join('')}${j.notes?`<p class="history-summary small" style="margin-top:12px">${esc(j.notes)}</p>`:''}`:'<p class="muted small">Wieczorna kartka czeka na Twoje słowa.</p>'}</section><section class="card"><h2>Ślady dnia</h2>${timeline(d.events)}</section><section class="card"><h2>Nawyki tego dnia</h2>${habitRows(true)}</section></div></div>`}
function listSettings(type,title){const items=data[type];return `<details class="card section"><summary>${title} <span class="small muted">${items.length}</span></summary><div class="section-body">${items.map(x=>`<div class="list-row"><div><strong>${esc(x.name)}</strong><small>${esc(x.group||x.dose|| (type==='drinks'?`${x.ml} ml`:''))}</small></div><div class="row">${btn('edit-category',icon('edit'),'icon-btn',`data-list="${type}" data-id="${x.id}" aria-label="Edytuj ${esc(x.name)}"`)}${btn('delete-category',icon('close'),'icon-btn',`data-list="${type}" data-id="${x.id}" aria-label="Usuń ${esc(x.name)}"`)}</div></div>`).join('')}${btn('new-category','Dodaj pozycję '+icon('plus'),'text-btn',`data-list="${type}"`)}</div></details>`}
function settingsView(){return `<div class="page-head"><p class="eyebrow">Po Twojemu</p><h1>Mój notes</h1></div><div class="grid"><div class="stack"><section class="card"><h2>Wygląd</h2>${options('Motyw','theme',[['system','Jak w telefonie'],['light','Jasny'],['dark','Ciemny']],data.settings.theme)}<p class="small muted">Dzień dziennika kończy się o 4:00. Wpis po północy należy jeszcze do poprzedniego dnia.</p></section><section class="card"><h2>Twoje dane</h2><p class="small muted">Wpisy i zdjęcia są zapisane wyłącznie w tej przeglądarce na tym urządzeniu. Usunięcie danych witryny usuwa również dziennik. Pobieraj kopie i przechowuj je poza aplikacją.</p><div class="stack" style="gap:10px">${btn('backup',icon('download')+' Pobierz pełną kopię','primary')}${btn('import','Przywróć z kopii','secondary')}${btn('csv','Eksportuj wpisy do CSV','text-btn')}${btn('persistent','Chroń zapis przed automatycznym czyszczeniem','text-btn')}</div><p class="small muted" style="margin-top:15px">Kopia zawiera zdjęcia, wpisy i ustawienia. Nie jest szyfrowana. Przywrócenie zastępuje obecny dziennik.</p>${data.settings.lastBackup?`<p class="small muted">Ostatnia pobrana kopia: ${esc(new Date(data.settings.lastBackup).toLocaleString('pl'))}</p>`:''}<input type="file" accept=".json,application/json" id="backup-file" hidden></section><section class="card"><h2>Na telefonie</h2><p class="small muted">W Chrome wybierz menu ⋮ → „Dodaj do ekranu głównego” → „Zainstaluj”. Po pierwszym otwarciu aplikacja działa także bez internetu.</p>${btn('install','Instalacja aplikacji','secondary')}<p class="small muted" style="margin-top:16px">Health Connect i powiadomienia nie są jeszcze dostępne.</p></section></div><div class="stack">${listSettings('symptoms','Objawy')}${listSettings('meds','Leki i suplementy')}${listSettings('activities','Aktywności i zdarzenia')}${listSettings('drinks','Napoje')}</div></div>`}
function showModal(title,body,onSubmit){modal.innerHTML=`<div class="modal-head"><h2>${title}</h2>${btn('close-modal',icon('close'),'icon-btn','aria-label="Zamknij"')}</div><form id="modal-form">${body}</form>`;if(!modal.open)modal.showModal();$('#modal-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;if(button)button.disabled=true;try{await onSubmit(new FormData(e.currentTarget),e.currentTarget)}catch(err){toast(err.message||'Nie udało się zapisać.');if(button)button.disabled=false}}}
const actions=(label='Zapisz')=>`<div class="actions">${btn('close-modal','Anuluj','text-btn')}<button class="primary" type="submit">${label}</button></div>`;
function selectField(label,name,list,value){return `<label class="field"><span>${label}</span><select name="${name}" required><option value="">Wybierz…</option>${list.map(x=>`<option value="${esc(x.id)}" ${x.id===value?'selected':''}>${esc(x.name)}${x.group?' · '+esc(x.group):''}</option>`).join('')}</select></label>`}
function openEvent(type,id){const existing=dayOf(data,selected).events.find(e=>e.id===id)||(type==='sleep'?dayOf(data,selected).events.find(e=>e.type==='sleep'):null),e=existing||{},eventDate=selected;let body='';if(type==='mood')body=scale('Nastrój','mood',e.mood)+scale('Energia','energy',e.energy)+scale('Produktywność','productivity',e.productivity)+'<p class="small muted">Wybierz przynajmniej jedną ocenę. Pozostałe możesz pominąć.</p>';const listKey={drink:'drinks',symptom:'symptoms',med:'meds',activity:'activities'}[type];if(listKey){const list=[...data[listKey]];if(e.ref&&!list.some(x=>x.id===e.ref))list.push({id:e.ref,name:e.name});body=selectField(names[type],'ref',list,e.ref)+btn('inline-category','Dodaj nową pozycję','text-btn',`data-list="${listKey}" data-return-type="${type}"`);if(type==='drink')body+=textField('Ilość (ml)','ml',e.ml||250,'','number','min="1" max="10000" required');if(type==='symptom')body+=options('Nasilenie','severity',[[1,'łagodne'],[2,'umiarkowane'],[3,'silne']],e.severity||2);if(type==='med')body+=textField('Dawka (opcjonalnie)','dose',e.dose||'','np. 1 tabletka','text','maxlength="200"');if(type==='activity'){const linked=data.habits.filter(h=>habitDue(h,eventDate)&&h.mode!=='weekly');if(linked.length)body+=`<label class="field"><span>Odhacz również nawyk (opcjonalnie)</span><select name="habit"><option value="">Bez odhaczania</option>${linked.map(h=>`<option value="${h.id}">${esc(h.name)}</option>`).join('')}</select></label>`;}}
 if(type==='sleep')body=options('Jakość snu','quality',['słaby','normalny','głęboki'],e.quality)+textField('Długość snu — godziny (opcjonalnie)','hours',e.hours??'','','number','min="0" max="24" step="0.25"');
 if(type==='bowel')body=options('Jak było?','stool',['twarde','normalne','luźne'],e.stool)+ '<p class="small muted">Możesz dopisać szczegóły poniżej.</p>';
 body+=textField(type==='note'?'Twoja notatka':'Notatka (opcjonalnie)','note',e.note||'','Twoimi słowami…','textarea',`maxlength="20000" ${type==='note'?'required':''}`)+textField('Godzina','time',e.time||clockNow(),'','time','required')+`<p class="small muted">Dzień dziennika: ${prettyDate(eventDate)}. Godziny 00:00–03:59 należą do końca tego dnia.</p>`+actions();
 showModal(existing?'Edytuj wpis':names[type],body,async fd=>{const entry={id:e.id||uid(),type,time:fd.get('time'),note:fd.get('note').trim()};entry.timestamp=eventStamp(eventDate,entry.time);if(type==='mood'){for(const k of ['mood','energy','productivity'])if(fd.get(k))entry[k]=Number(fd.get(k));if(!['mood','energy','productivity'].some(k=>entry[k]!=null))throw Error('Wybierz przynajmniej jedną ocenę.');}if(listKey){const item=data[listKey].find(x=>x.id===fd.get('ref'))||(e.ref===fd.get('ref')?{id:e.ref,name:e.name}:null);if(!item)throw Error('Wybierz pozycję.');entry.ref=item.id;entry.name=item.name;}if(type==='drink')entry.ml=Number(fd.get('ml'));if(type==='symptom')entry.severity=Number(fd.get('severity'));if(type==='med')entry.dose=fd.get('dose').trim();if(type==='sleep'){if(!fd.get('quality'))throw Error('Wybierz jakość snu.');entry.quality=fd.get('quality');if(fd.get('hours'))entry.hours=Number(fd.get('hours'));}if(type==='bowel')entry.stool=fd.get('stool')||'zapisane';const day=ensureDay(data,eventDate),idx=day.events.findIndex(x=>x.id===entry.id);if(idx>=0)day.events[idx]=entry;else day.events.push(entry);if(fd.get('habit')){const h=data.habits.find(h=>h.id===fd.get('habit'));const checks=day.checks[h.id]??=Array(h.target).fill(false);const empty=Array.from({length:h.target},(_,i)=>i).find(i=>!checks[i]);if(empty!=null)checks[empty]=true;}await persist({date:eventDate});modal.close();render();toast('Zapisano wpis');});
 const selector=$('select[name=ref]',modal);if(selector)selector.onchange=()=>{const x=data[listKey].find(x=>x.id===selector.value);if(type==='drink'&&x)$('[name=ml]',modal).value=x.ml;if(type==='med'&&x)$('[name=dose]',modal).value=x.dose||'';};
}
function openHabit(id){const old=data.habits.find(h=>h.id===id),h=old||{name:'',mode:'daily',target:1,weekdays:[2,4,6],slots:[],time:''};showModal(old?'Edytuj nawyk':'Nowy mały krok',textField('Nazwa','name',h.name,'np. Czytanie','text','required maxlength="200"')+options('Kiedy?','mode',[['daily','Codziennie'],['days','Wybrane dni'],['weekly','Cel tygodniowy']],h.mode)+`<div id="weekdays" ${h.mode==='days'?'':'hidden'}><fieldset><legend>Dni tygodnia</legend><div class="choices">${[[1,'Pn'],[2,'Wt'],[3,'Śr'],[4,'Cz'],[5,'Pt'],[6,'So'],[0,'Nd']].map(([n,t])=>`<label class="choice"><input type="checkbox" name="weekdays" value="${n}" ${h.weekdays.includes(n)?'checked':''}><span>${t}</span></label>`).join('')}</div></fieldset></div>`+textField('Liczba wykonań (dziennie lub tygodniowo)','target',h.target,'','number','required min="1" max="20" step="1"')+textField('Nazwy odhaczeń, oddzielone przecinkiem','slots',h.slots.join(', '),'np. rano, wieczorem','text','maxlength="500"')+textField('Godzina w planie (bez powiadomienia)','time',h.time||'','','time')+`<p class="small muted">Przy celu tygodniowym wybierasz dowolne dni. Zmiana harmonogramu dotyczy także jego widoku w historii; odhaczenia pozostają zapisane.</p>${old?btn('archive-habit','Zakończ i przenieś do archiwum','text-btn danger',`data-id="${h.id}"`):''}`+actions(),async fd=>{const weekdays=fd.getAll('weekdays').map(Number),mode=fd.get('mode');if(mode==='days'&&!weekdays.length)throw Error('Wybierz przynajmniej jeden dzień.');const next={...h,id:h.id||uid(),name:fd.get('name').trim(),mode,target:Number(fd.get('target')),weekdays,slots:fd.get('slots').split(',').map(s=>s.trim()).filter(Boolean).slice(0,20),time:fd.get('time'),startDate:h.startDate||selected};if(!next.name)throw Error('Podaj nazwę.');if(old)Object.assign(old,next);else data.habits.push(next);await persist();modal.close();render();toast('Zapisano nawyk');});$$('[name=mode]',modal).forEach(r=>r.onchange=()=>$('#weekdays',modal).hidden=r.value!=='days')}
function openCategory(list,id,returnType){const old=data[list].find(x=>x.id===id),x=old||{};showModal(old?'Edytuj pozycję':'Nowa pozycja',textField('Nazwa','name',x.name||'','','text','required maxlength="200"')+(list==='symptoms'?textField('Kategoria','group',x.group||'Inne','','text','required maxlength="200"'):'')+(list==='meds'?textField('Domyślna dawka','dose',x.dose||'','np. 1 tabletka','text','maxlength="200"'):'')+(list==='drinks'?textField('Domyślna porcja (ml)','ml',x.ml||250,'','number','required min="1" max="10000"'):'')+actions(),async fd=>{const next={...x,id:x.id||uid(),name:fd.get('name').trim()};if(!next.name)throw Error('Podaj nazwę.');if(list==='symptoms')next.group=fd.get('group').trim()||'Inne';if(list==='meds')next.dose=fd.get('dose').trim();if(list==='drinks')next.ml=Number(fd.get('ml'));if(old)Object.assign(old,next);else data[list].push(next);await persist();modal.close();render();if(returnType){openEvent(returnType);const select=$('[name=ref]',modal);select.value=next.id;select.dispatchEvent(new Event('change'));}else toast('Zapisano');})}
function confirmAction(title,message,action,label='Usuń'){showModal(title,`<p>${message}</p>`+actions(label),async()=>{await action();modal.close();render()})}
async function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
async function backup(){await saveQueue;const snapshot=structuredClone(data);snapshot.exportedAt=new Date().toISOString();await download(`blisko-kopia-${dateKey()}-${Date.now()}.json`,JSON.stringify(snapshot),'application/json');if(!saveError){data.settings.lastBackup=snapshot.exportedAt;await persist();if(view==='settings')render()}toast('Kopia została przygotowana do pobrania')}
async function importBackup(file){if(!file)return;if(file.size>150*1024*1024)throw Error('Kopia jest większa niż 150 MB.');const candidate=validateBackup(JSON.parse(await file.text()));const count=Object.keys(candidate.days).length;showModal('Przywrócić dziennik?',`<p>Ta kopia zawiera ${count} dni. Zastąpi obecne wpisy, zdjęcia, nawyki i ustawienia.</p><p class="small muted">Najpierw pobierz kopię obecnego dziennika, jeśli chcesz go zachować.</p>${btn('backup','Pobierz obecną kopię','secondary')}${actions('Zastąp dziennik')}`,async()=>{await saveQueue;candidate.rev=data.rev;data=candidate;await persist({all:true});selected=effectiveDate();modal.close();render();toast('Przywrócono dziennik');})}
function exportCsv(){const rows=[['data_dziennika','godzina','kategoria','nazwa','nastroj','energia','produktywnosc','ilosc_ml','nasilenie','notatka']];Object.keys(data.days).sort().forEach(date=>{const d=data.days[date];d.events.forEach(e=>rows.push([date,e.time,names[e.type],eventLabel(e),e.mood??'',e.energy??'',e.productivity??'',e.ml??'',e.severity??'',e.note||'']));if(Object.keys(d.journal).length)rows.push([date,'','Refleksja','Ocena dnia: '+(d.journal.rating??'—'),'','','','','',Object.entries(d.journal).filter(([k])=>k!=='photo').map(([k,v])=>`${k}: ${Array.isArray(v)?v.join(', '):v}`).join('\n')]);Object.entries(d.checks).forEach(([id,checks])=>{const h=data.habits.find(h=>h.id===id);if(h)rows.push([date,'','Nawyk',h.name,'','','','','',`${checks.filter(Boolean).length} wykonania`])})});const cell=v=>{let s=String(v);if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};download(`blisko-wpisy-${dateKey()}.csv`,'\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8')}
async function addPhoto(file){if(!file)return;if(!file.type.startsWith('image/'))throw Error('Wybierz plik ze zdjęciem.');if(file.size>40*1024*1024)throw Error('Wybierz zdjęcie mniejsze niż 40 MB.');const key=selected;let image;try{image=await createImageBitmap(file,{imageOrientation:'from-image'})}catch{throw Error('Nie udało się odczytać zdjęcia. Wybierz JPG, PNG lub WebP.')}const ratio=Math.min(1,1600/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*ratio);canvas.height=Math.round(image.height*ratio);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);image.close();ensureDay(data,key).journal.photo=canvas.toDataURL('image/jpeg',.82);await persist({date:key});render();toast('Zdjęcie zapisane w dzienniku')}
async function install(){if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;return}showModal('Blisko na Twoim telefonie',`<p>W Chrome na Androidzie otwórz menu <strong>⋮</strong>, następnie wybierz <strong>„Dodaj do ekranu głównego”</strong> i <strong>„Zainstaluj”</strong>.</p><p class="small muted">Jeśli aplikacja jest już zainstalowana, otwórz ją z ekranu głównego. Po pierwszym uruchomieniu z internetem dziennik działa także offline.</p>`+actions('Rozumiem'),()=>modal.close())}
document.addEventListener('click',async event=>{const target=event.target.closest('[data-action]');if(!target||target.disabled||!data)return;const a=target.dataset.action,id=target.dataset.id;try{
 if(a==='nav')navigate(target.dataset.view);
 else if(['journal','habits','settings'].includes(a))navigate(a);
 else if(a==='prev'||a==='next'||a==='today'){selected=a==='today'?effectiveDate():addDays(selected,a==='prev'?-1:1);calendarMonth=selected.slice(0,7);collapsed.clear();render()}
 else if(a==='close-modal')modal.close();
 else if(a==='add-event')openEvent(target.dataset.type);
 else if(a==='edit-event'){const e=dayOf(data,selected).events.find(e=>e.id===id);openEvent(e.type,id)}
 else if(a==='delete-event'){const key=selected;confirmAction('Usunąć wpis?','Ten wpis zniknie z historii dnia.',async()=>{const d=ensureDay(data,key);d.events=d.events.filter(e=>e.id!==id);await persist()})}
 else if(a==='need-chip'){const j=ensureDay(data,selected).journal,key=target.dataset.key,val=target.dataset.value,tags=j[key]??=[];j[key]=tags.includes(val)?tags.filter(v=>v!==val):[...tags,val];target.classList.toggle('selected',j[key].includes(val));target.setAttribute('aria-pressed',j[key].includes(val));await persist()}
 else if(a==='remove-photo'){confirmAction('Usunąć zdjęcie?','Zdjęcie zostanie usunięte z tej kartki.',async()=>{delete ensureDay(data,selected).journal.photo;await persist()})}
 else if(a==='new-habit'||a==='edit-habit')openHabit(id);
 else if(['habit-check','habit-increment','habit-undo'].includes(a)){const h=data.habits.find(h=>h.id===id),d=ensureDay(data,selected),checks=d.checks[id]??=Array(h.mode==='weekly'?0:h.target).fill(false);if(a==='habit-check'){const slot=Number(target.dataset.slot);checks[slot]=!checks[slot]}else if(a==='habit-increment'&&habitCount(data,h,selected)<h.target)checks.push(true);else if(a==='habit-undo')checks.pop();await persist();render()}
 else if(a==='archive-habit'){const h=data.habits.find(h=>h.id===id);confirmAction('Zakończyć nawyk?',`„${esc(h.name)}” trafi do archiwum. Dotychczasowe odhaczenia pozostaną w historii.`,async()=>{h.endDate=effectiveDate();await persist()},'Przenieś do archiwum')}
 else if(a==='restore-habit'){const h=data.habits.find(h=>h.id===id);data.habits.push({...structuredClone(h),id:uid(),startDate:effectiveDate(),endDate:undefined});await persist();render()}
 else if(a==='new-category'||a==='edit-category'||a==='inline-category')openCategory(target.dataset.list,id,target.dataset.returnType);
 else if(a==='delete-category'){const list=target.dataset.list;confirmAction('Usunąć pozycję?', 'Usunięcie z listy nie zmienia już zapisanych wpisów.',async()=>{data[list]=data[list].filter(x=>x.id!==id);await persist()})}
 else if(a==='range'){range=Number(target.dataset.range);render()}
 else if(a==='month-prev'||a==='month-next'){const d=new Date(calendarMonth+'-01T12:00:00');d.setMonth(d.getMonth()+(a==='month-prev'?-1:1));calendarMonth=dateKey(d).slice(0,7);render()}
 else if(a==='calendar-day'){selected=target.dataset.date;render()}
 else if(a==='backup')await backup();
 else if(a==='import')$('#backup-file').click();
 else if(a==='csv')exportCsv();
 else if(a==='persistent'){const granted=await navigator.storage?.persist?.();toast(granted?'Przeglądarka chroni lokalne dane. Nadal rób kopie.':'Przeglądarka nie przyznała ochrony. Regularnie pobieraj kopie.')}
 else if(a==='install')await install();
 }catch(e){toast(e.message||'Coś poszło nie tak. Spróbuj ponownie.')}});
document.addEventListener('input',event=>{const el=event.target;if(!el.matches('[data-journal]')||el.type==='radio')return;const j=ensureDay(data,selected).journal;if(el.value)j[el.name]=el.value;else delete j[el.name];persist().catch(()=>{})});
document.addEventListener('change',async event=>{const el=event.target;try{if(el.id==='selected-date'){if(!validDate(el.value)||el.value>effectiveDate()){el.value=selected;return}selected=el.value;calendarMonth=selected.slice(0,7);collapsed.clear();render()}else if(el.matches('[data-journal]')&&el.type==='radio'){ensureDay(data,selected).journal[el.name]=el.name==='rating'?Number(el.value):el.value;await persist()}else if(el.name==='theme'){data.settings.theme=el.value;applyTheme();await persist()}else if(el.id==='day-photo')await addPhoto(el.files[0]);else if(el.id==='backup-file'){await importBackup(el.files[0]);el.value=''}}catch(e){toast(e.message||'Nie udało się odczytać pliku.')}});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event});
window.addEventListener('beforeunload',event=>{if(savePending||saveError){event.preventDefault();event.returnValue=''}});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>data&&applyTheme());
async function boot(){try{data=await openDB();if(!data){data=freshData();await persist()}applyTheme();render();if('serviceWorker'in navigator){await navigator.serviceWorker.register('./sw.js');navigator.serviceWorker.addEventListener('message',e=>{if(e.data==='update-ready')toast('Nowa wersja będzie dostępna po ponownym otwarciu aplikacji.')})}registerTools();}catch(e){if(!data)app.innerHTML=`<main class="loading"><h1>Nie można otworzyć dziennika</h1><p>Sprawdź, czy przeglądarka zezwala na zapis danych witryny, i otwórz aplikację ponownie.</p><p>${esc(e.message)}</p></main>`;else toast('Dziennik działa, ale nie udało się przygotować trybu offline. Otwórz go ponownie z internetem.')}}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(context.registerTool({name:'open_journal_day',title:'Otwórz dzień dziennika',description:'Opens the selected journal day in the visible app. Does not modify stored health data.',inputSchema:{type:'object',properties:{date:{type:'string',description:'Journal date YYYY-MM-DD, no later than today'}},required:['date'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:async input=>{if(!input||!validDate(input.date)||input.date>effectiveDate())throw Error('Invalid journal date');selected=input.date;navigate('journal');return {date:selected,view:'journal'}}},{signal:lifecycle.signal})).catch(()=>{})}catch{}}
boot();
